source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    marker_color = min((v for v in counts if v != 0), key=lambda v: counts[v])
    q = deque()
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color:
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r,c in seen: out[r][c]=marker_color
    return out
'''
