 co=Counter(x for row in g for x in row); marker=min((x for x in co if x!=0),key=lambda x:co[x]); pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==marker]; r0=min(r for r,c in pts); c0=min(c for r,c in pts); shape={(r-r0,c-c0) for r,c in pts}; return marker,shape

